css:
.fp { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .4rem 2rem; font-size: .95rem; color: var(--os-color-text-muted); }
.fp p { margin: 0; max-width: none; }
.fp a { color: var(--os-color-heading); }
.fp.is-row { width: min(100% - 2 * clamp(1.1rem, 4vw, 2.5rem), 1180px); margin: 0 auto; padding: 1.4rem 0 2.2rem; border-top: 1px solid var(--bff-line, rgba(21,38,26,.22)); }
